import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Custom fused operator for Flatten + Linear projection in one CUDA kernel
fused_flatten_linear_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cstdio>

// A naive fused kernel that flattens a 4D input [B, C, H, W] and
// multiplies by weight [out_features, in_features], adds bias [out_features].
__global__ void fused_flatten_linear_kernel(
    const float* __restrict__ x,        // [B, C, H, W]
    const float* __restrict__ weight,   // [out_features, in_features]
    const float* __restrict__ bias,     // [out_features]
    float* __restrict__ out,           // [B, out_features]
    int B, int C, int H, int W,
    int out_features, int in_features)
{
    // Each thread computes one element in [B, out_features].
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < B * out_features) {
        int i = idx / out_features;        // batch index
        int j = idx % out_features;        // out_feature index

        float sumVal = 0.0f;
        // Naive flatten loop
        for (int k = 0; k < in_features; k++) {
            // Flatten index to c,h,w
            // in_features = C*H*W
            // c = k / (H*W), remainder = k % (H*W)
            // h = remainder / W, w = remainder % W
            int c = k / (H*W);
            int r = k % (H*W);
            int h = r / W;
            int w = r % W;
            float val_x = x[ i*C*H*W + c*H*W + h*W + w ];
            float val_w = weight[ j*in_features + k ];
            sumVal += val_x * val_w;
        }
        // Add bias
        sumVal += bias[j];
        out[i * out_features + j] = sumVal;
    }
}

torch::Tensor fused_flatten_linear_cuda(
    torch::Tensor x,           // [B, C, H, W]
    torch::Tensor weight,      // [out_features, in_features]
    torch::Tensor bias,        // [out_features]
    int B,
    int C,
    int H,
    int W,
    int out_features,
    int in_features)
{
    auto out = torch::zeros({B, out_features}, x.options());
    int totalThreads = B * out_features;
    const int blockSize = 256;
    int gridSize = (totalThreads + blockSize - 1) / blockSize;

    fused_flatten_linear_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C, H, W,
        out_features, in_features
    );
    return out;
}
""";

fused_flatten_linear_cpp_source = r"""
torch::Tensor fused_flatten_linear_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int B,
    int C,
    int H,
    int W,
    int out_features,
    int in_features);
""";

# Build the fused flatten+linear operator
fused_flatten_linear = load_inline(
    name="fused_flatten_linear",
    cpp_sources=fused_flatten_linear_cpp_source,
    cuda_sources=fused_flatten_linear_source,
    functions=["fused_flatten_linear_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, num_classes, embed_dim=512, num_heads=8, num_layers=6, 
                 mlp_ratio=4.0, patch_size=4, in_channels=3):
        super(ModelNew, self).__init__()
        self.patch_size = patch_size
        self.conv1 = nn.Conv2d(in_channels, embed_dim, kernel_size=patch_size, stride=patch_size)
        self.flatten = nn.Flatten()  # Not used in forward anymore, kept for shape reference
        self.linear_proj = nn.Linear(embed_dim * (32 // patch_size) * (32 // patch_size), embed_dim)

        self.transformer_layers = nn.ModuleList([
            nn.TransformerEncoderLayer(d_model=embed_dim, nhead=num_heads,
                                       dim_feedforward=int(embed_dim * mlp_ratio), dropout=0.0)
            for _ in range(num_layers)
        ])

        self.cls_token = nn.Parameter(torch.zeros(1, 1, embed_dim))
        self.fc_out = nn.Linear(embed_dim, num_classes)

        self.fused_flatten_linear = fused_flatten_linear

    def forward(self, x):
        B, C, H, W = x.shape
        x = self.conv1(x)  # shape [B, embed_dim, H/patch_size, W/patch_size]

        # Instead of a separate flatten + linear, use custom fused operator
        B2, C2, H2, W2 = x.shape  # [B, embed_dim, H/ps, W/ps]
        out_features = self.linear_proj.out_features  # embed_dim
        in_features = C2 * H2 * W2
        x = self.fused_flatten_linear.fused_flatten_linear_cuda(
            x, 
            self.linear_proj.weight, 
            self.linear_proj.bias, 
            B2, 
            C2, 
            H2, 
            W2, 
            out_features, 
            in_features
        )

        # Add cls token
        cls_tokens = self.cls_token.expand(B, -1, -1)  # (B, 1, embed_dim)
        x = torch.cat((cls_tokens, x.unsqueeze(1)), dim=1)  # (B, 1+N, embed_dim)

        # Transformer layers
        for layer in self.transformer_layers:
            x = layer(x)

        # Classify
        x = x[:, 0]  # CLS token output
        x = self.fc_out(x)
        return x
